const ChatInterface = () => {
  return (
    <form action="">
      <div>
        <input
          type="text"
          name="message"
          aria-label="Напишите ваш вопрос"
          placeholder="Напишите ваш вопрос..."
        />
        <button type="submit">Отправить</button>
      </div>
    </form>
  );
};

export default ChatInterface;
